const leafMats=[material(0x8bae3c),material(0x6f9d33),material(0x8db748),material(0x73a742)];
const edgeMat=material(0x4f812e),veinMat=new THREE.LineBasicMaterial({color:0xc9dc78,transparent:true,opacity:.23});
function mesh(geo,mat,x=0,y=0,z=0,parent=scene){const m=new THREE.Mesh(geo,mat);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
const sphereG=new THREE.SphereGeometry(1,20,14);
function ellipsoid(parent,mat,x,y,z,sx,sy,sz){const m=mesh(sphereG,mat,x,y,z,parent);m.scale.set(sx,sy,sz);return m}
function cylinderBetween(a,b,r,mat,parent){const d=new THREE.Vector3().subVectors(b,a);const m=mesh(new THREE.CylinderGeometry(r*.65,r,d.length(),5),mat,0,0,0,parent);m.position.copy(a).add(b).multiplyScalar(.5);m.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),d.normalize());return m;}

// Water is a low-frequency animated shader with sunlight glints and shallow ripples.
const waterUniforms={time:{value:0},color:{value:new THREE.Color(CHAPTERS[0].water)},fogColor:{value:scene.fog.color},fogDensity:{value:.027}};
const waterMat=new THREE.ShaderMaterial({uniforms:waterUniforms,vertexShader:`varying vec3 vWorld;uniform float time;void main(){vec3 p=position;p.z+=sin(p.x*.45+time*.7)*.04+cos(p.y*.4+time*.6)*.03;vec4 w=modelMatrix*vec4(p,1.);vWorld=w.xyz;gl_Position=projectionMatrix*viewMatrix*w;}`,fragmentShader:`varying vec3 vWorld;uniform float time;uniform vec3 color;uniform vec3 fogColor;uniform float fogDensity;void main(){float a=sin(vWorld.x*.72+vWorld.z*.3+time*.5);float b=sin(vWorld.x*.2-vWorld.z*.95-time*.4);float c=sin(vWorld.x*2.1+vWorld.z*1.7+time*.8);float glint=pow(max(0.,a*b*c),18.);float broad=sin(vWorld.x*.15+vWorld.z*.18)*.05;vec3 col=color*(.83+a*.035+b*.025+broad)+vec3(.55,.8,.61)*glint*.22;float dist=gl_FragCoord.z/gl_FragCoord.w;float fog=1.-exp(-fogDensity*fogDensity*dist*dist);gl_FragColor=vec4(mix(col,fogColor,clamp(fog,0.,1.)),1.);}`});
const water=mesh(new THREE.PlaneGeometry(300,330,90,90),waterMat,0,-.10,-55);water.rotation.x=-Math.PI/2;water.castShadow=false;
const shadowG=new THREE.CircleGeometry(1,40),waterShadowMat=new THREE.MeshBasicMaterial({color:0x123f39,transparent:true,opacity:.18,depthWrite:false});
function leafGeometry(r){const s=new THREE.Shape();s.moveTo(0,0);for(let i=0;i<=48;i++){const a=.16+i/48*(Math.PI*2-.34);const rr=r*(1+Math.sin(a*5)*.017);s.lineTo(Math.cos(a)*rr,Math.sin(a)*rr)}s.lineTo(0,0);const g=new THREE.ExtrudeGeometry(s,{depth:.14,bevelEnabled:true,bevelSegments:1,steps:1,bevelSize:.04,bevelThickness:.03,curveSegments:32});g.rotateX(-Math.PI/2);return g}
const pads=makeLayout().map((data,i)=>{
 const group=new THREE.Group();scene.add(group);group.position.set(data.x,.18,data.z);group.rotation.y=data.phase*.45;
 const mat=data.type==='bonus'?material(0xb4b44a):data.type==='sinking'?material(0xb59c4b):data.type==='moving'?material(0x6eada1):leafMats[i%4];
 const body=mesh(leafGeometry(data.r),mat,0,0,0,group);body.userData.padId=data.id;
 for(let a=.35;a<Math.PI*2-.3;a+=.65){const points=[new THREE.Vector3(.12,.18,0),new THREE.Vector3(Math.cos(a)*data.r*.45,.184,-Math.sin(a)*data.r*.45),new THREE.Vector3(Math.cos(a)*data.r*.91,.184,-Math.sin(a)*data.r*.91)];group.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(points),veinMat));}
 const shadow=mesh(shadowG,waterShadowMat,data.x,.005,data.z);shadow.rotation.x=-Math.PI/2;shadow.scale.setScalar(data.r*1.1);shadow.castShadow=false;
 const p={...data,group,body,shadow,baseX:data.x,baseZ:data.z,visited:false,sink:0};
 if(data.type==='checkpoint'&&i>0){addFlower(group,data.r*.6,.13,.15,.52);const ring=mesh(new THREE.TorusGeometry(data.r*.77,.018,5,64),new THREE.MeshBasicMaterial({color:0xe4efa7,transparent:true,opacity:.6}),0,.2,0,group);ring.rotation.x=Math.PI/2;}
 if(data.type==='spring'){addFlower(group,0,.15,0,.72);}
 if(data.type==='bonus')addFlower(group,-.35,.15,.2,.3);
 return p;
});
const pink=material(0xf8a3be),pink2=material(0xe875a4),creamPink=material(0xffd1d2),flowerCore=material(0xffd874),stemMat=material(0x638c39);
// Hoisted flower helper creates petal geometry on demand during world construction.
function addFlower(parent,x,y,z,size=1){
 const g=new THREE.Group();g.position.set(x,y,z);g.scale.setScalar(size);parent.add(g);
 const petalMat=material(0xf1a1b5),innerMat=material(0xffc8d0);
 for(let j=0;j<2;j++)for(let i=0;i<7;i++){const a=i*Math.PI*2/7+j*.4;const petal=ellipsoid(g,j?innerMat:petalMat,Math.cos(a)*(.34-j*.14),.2+j*.19,Math.sin(a)*(.34-j*.14),.20,.37,.12);petal.rotation.z=-Math.cos(a)*.8;petal.rotation.x=Math.sin(a)*.8;petal.rotation.y=-a;}
 ellipsoid(g,material(0xf2cc64),0,.34,0,.2,.12,.2);return g;
}

// Living banks: low-poly reeds, stones, scattered blossoms and smaller lily pads.
let seed=14851;function rand(){seed=(seed*16807)%2147483647;return(seed-1)/2147483646}
const decorations=new THREE.Group();scene.add(decorations);
for(let i=0;i<102;i++){
 const z=13-rand()*163,x=(rand()>.5?1:-1)*(7+rand()*19),r=.5+rand()*1.6;
 const g=new THREE.Group();g.position.set(x,.05+rand()*.08,z);g.rotation.y=rand()*6;decorations.add(g);const l=mesh(leafGeometry(r),leafMats[i%4],0,0,0,g);l.castShadow=false;
 if(i%3===0)addFlower(g,-r*.15,.13,r*.08,.4+rand()*.6);
 if(i%2===0){const stem=material(i%4===0?0x527b47:0x6e923f);for(let k=0;k<3;k++){let a=rand()*6;const h=1+rand()*2;cylinderBetween(new THREE.Vector3(x+Math.cos(a)*r,.05,z+Math.sin(a)*r),new THREE.Vector3(x+Math.cos(a)*r+.15,h,z+Math.sin(a)*r-.2),.04,stem,decorations);if(k===0)ellipsoid(decorations,material(0x746143),x+Math.cos(a)*r+.15,h,z+Math.sin(a)*r-.2,.095,.3,.095)}}
}
