const frog=new THREE.Group();scene.add(frog);
const green=material(0x90c747,.58),darkGreen=material(0x67a83d,.66),belly=material(0xe6efac),eyeWhite=material(0xf5f5d4,.3),black=material(0x20382c,.2),blush=material(0xe59b7f);
const body=ellipsoid(frog,green,0,.52,0,.58,.43,.69);const tummy=ellipsoid(frog,belly,0,.4,-.40,.43,.27,.29);const head=ellipsoid(frog,green,0,.8,-.33,.59,.34,.46);
const legs=[];for(const side of [-1,1]){legs.push(ellipsoid(frog,darkGreen,side*.5,.24,.3,.35,.23,.43));ellipsoid(frog,green,side*.61,.10,.10,.26,.105,.37);ellipsoid(frog,green,side*.38,.28,-.42,.15,.25,.15);ellipsoid(frog,green,side*.41,.075,-.51,.22,.07,.21);ellipsoid(frog,green,side*.36,1.02,-.42,.25,.26,.24);ellipsoid(frog,eyeWhite,side*.36,1.07,-.6,.195,.2,.12);ellipsoid(frog,black,side*.36,1.08,-.7,.087,.125,.041);ellipsoid(frog,eyeWhite,side*.34,1.13,-.733,.029,.034,.012);ellipsoid(frog,blush,side*.45,.74,-.672,.11,.055,.035);for(let j=0;j<3;j++)ellipsoid(frog,green,side*(.34+j*.08),.057,-.65,.062,.05,.12);}
const smilePoints=[];for(let i=0;i<=20;i++){const x=-.20+i*.02;smilePoints.push(new THREE.Vector3(x,.714-.065*(1-(x/.2)**2),-.754+Math.abs(x)*.12))}const smile=new THREE.Line(new THREE.BufferGeometry().setFromPoints(smilePoints),new THREE.LineBasicMaterial({color:0x3c6530}));frog.add(smile);
for(let i=0;i<6;i++)ellipsoid(frog,darkGreen,(rand()-.5)*.7,.85,rand()*.7-.05,.06,.02,.08);
frog.rotation.y=Math.PI*.2;frog.position.set(0,.4,0);
const frogShadow=mesh(shadowG,new THREE.MeshBasicMaterial({color:0x1d4d30,transparent:true,opacity:.25,depthWrite:false}),0,.4,0);frogShadow.rotation.x=-Math.PI/2;frogShadow.castShadow=false;frogShadow.scale.set(.74,.58,1);
const shieldRing=mesh(new THREE.TorusGeometry(.96,.016,5,64),new THREE.MeshBasicMaterial({color:0xc4edff,transparent:true,opacity:.75}),0,.5,0,frog);shieldRing.rotation.x=Math.PI/2;shieldRing.visible=false;

const collectables=[];
for(const p of pads){if(p.id===0)continue;const g=new THREE.Group();scene.add(g);const color=p.type==='bonus'?0xffd37a:p.type==='shield'?0xc1f2ff:0xf6ed9d;const core=mesh(new THREE.OctahedronGeometry(p.type==='bonus'?.2:.12,0),new THREE.MeshBasicMaterial({color}),0,0,0,g);const glow=mesh(new THREE.SphereGeometry(.25,12,8),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.08,depthWrite:false}),0,0,0,g);if(p.type==='bonus')glow.scale.setScalar(1.8);collectables.push({pad:p,group:g,core})}
const dragonflies=[];for(let i=0;i<13;i++){const g=new THREE.Group();scene.add(g);const m=new THREE.MeshBasicMaterial({color:i%2?0xffd8a1:0xbcffe4});ellipsoid(g,m,0,0,0,.04,.035,.22);const wings=[];for(const s of [-1,1]){const w=ellipsoid(g,new THREE.MeshBasicMaterial({color:0xedffe8,transparent:true,opacity:.45}),s*.19,.02,0,.22,.009,.07);wings.push(w)}dragonflies.push({g,wings,x:(rand()-.5)*22,z:9-rand()*145,phase:rand()*6})}

const targetRing=mesh(new THREE.TorusGeometry(1,.025,5,80),new THREE.MeshBasicMaterial({color:0xe5ffae,transparent:true,opacity:.85}),0,.45,0);targetRing.rotation.x=-Math.PI/2;targetRing.castShadow=false;
const targetDot=mesh(new THREE.ConeGeometry(.12,.26,4),new THREE.MeshBasicMaterial({color:0xf4ffd7}),0,1,0);targetDot.rotation.x=Math.PI;targetDot.castShadow=false;
const arcDots=[];for(let i=0;i<22;i++){const dot=mesh(new THREE.SphereGeometry(.045,7,5),new THREE.MeshBasicMaterial({color:0xebf9bc,transparent:true,opacity:.55}),0,0,0);dot.castShadow=false;arcDots.push(dot)}
const landingRing=mesh(new THREE.TorusGeometry(.26,.023,4,40),new THREE.MeshBasicMaterial({color:0xf2ffc1}),0,.5,0);landingRing.rotation.x=Math.PI/2;landingRing.castShadow=false;landingRing.visible=false;
const particles=[],ripples=[];
function splash(x,z,good=false){for(let i=0;i<18;i++){const mat=new THREE.MeshBasicMaterial({color:good?0xe6f990:0xa0e8d7,transparent:true,opacity:.85});const m=mesh(new THREE.SphereGeometry(.04+Math.random()*.04,5,4),mat,x,.25,z);m.castShadow=false;const a=Math.random()*6.28,v=.5+Math.random()*2;particles.push({m,v:new THREE.Vector3(Math.cos(a)*v,1+Math.random()*2,Math.sin(a)*v),life:1,age:0})}for(let i=0;i<2;i++){const m=mesh(new THREE.RingGeometry(.95,1,60),new THREE.MeshBasicMaterial({color:good?0xe0f8bc:0xa1dec7,transparent:true,opacity:.35,side:THREE.DoubleSide,depthWrite:false}),x,.03+i*.005,z);m.rotation.x=-Math.PI/2;m.castShadow=false;ripples.push({m,age:-i*.2})}}

let audioCtx=null,lastAmbient=0;
function initAudio(){if(!audioCtx){try{audioCtx=new(window.AudioContext||window.webkitAudioContext)()}catch{}}audioCtx?.resume();}
function tone(freq=440,duration=.1,type='sine',gain=.025,end=null){if(!state.audio||!audioCtx)return;const osc=audioCtx.createOscillator(),g=audioCtx.createGain();osc.type=type;osc.frequency.setValueAtTime(freq,audioCtx.currentTime);if(end)osc.frequency.exponentialRampToValueAtTime(end,audioCtx.currentTime+duration);g.gain.setValueAtTime(.0001,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(gain,audioCtx.currentTime+.018);g.gain.exponentialRampToValueAtTime(.0001,audioCtx.currentTime+duration);osc.connect(g).connect(audioCtx.destination);osc.start();osc.stop(audioCtx.currentTime+duration);}
function melody(kind){if(kind==='land'){tone(610,.13,'sine',.04);setTimeout(()=>tone(860,.18,'sine',.022),80)}if(kind==='collect'){[660,880,1100].forEach((v,i)=>setTimeout(()=>tone(v,.22,'sine',.025),i*70))}if(kind==='fall')tone(280,.5,'sine',.045,65);if(kind==='jump')tone(190,.20,'sine',.05,560);}
function toast(text,duration=3){$('toast').textContent=text;$('toast').classList.add('show');state.toastTime=duration;}
function currentPad(){return pads.find(p=>p.id===state.current)}
function selectedPad(){return pads.find(p=>p.id===state.selected)}
function padTop(p){return p.group.position.y+.19}
function candidates(){const cur=currentPad();return pads.filter(p=>p.id!==cur.id&&p.index>=state.progress&&p.index<=state.progress+2&&p.id!==0&&!(p.type==='bonus'&&state.collected.has(p.id))&&distance(cur.group.position,p.group.position)<(cur.type==='spring'?10.2:8.1)&&p.group.position.z<cur.group.position.z+.2).sort((a,b)=>a.group.position.x-b.group.position.x)}
function selectDefault(){const next=pads[Math.min(TOTAL,state.progress+1)];state.selected=next.id;updateTarget()}
function updateTarget(){const p=selectedPad();if(!p)return;const names={moving:'漂移荷叶',sinking:'下沉荷叶 · 停留 3 秒',spring:'弹跳花 · 下一跳更远',checkpoint:p.index===30?'终点 · 月光花岛':'荷花存档点',bonus:'金色露光 · 支线奖励',shield:'水滴护盾',normal:'下一片荷叶'};$('target-label').textContent=names[p.type];}
function cycleTarget(direction){if(state.mode!=='play'||state.flight||state.charging)return;const list=candidates();if(!list.length)return;let i=list.findIndex(p=>p.id===state.selected);state.selected=list[(i+direction+list.length)%list.length].id;updateTarget();tone(440,.04,'sine',.008)}
function setTheme(index,immediate=false){state.preview=index;const c=CHAPTERS[index];$('weather').innerHTML=c.name+' <i></i> '+(index===0?'22°':index===1?'19°':'16°');$('preview-title').textContent=c.name;$('preview-desc').textContent=c.description;$('chapter-card').querySelector('.eyebrow span').textContent=`0${index+1} / 03`;document.querySelectorAll('.chapter').forEach((el,i)=>el.classList.toggle('active',i===index));if(immediate){waterUniforms.color.value.set(c.water);scene.fog.color.set(c.fog);scene.background.set(c.fog);sun.color.set(c.light);hemi.color.set(c.ambient)}}
function saveProgress(){try{localStorage.setItem('lilybound-save',JSON.stringify({checkpoint:state.checkpoint,nectar:state.nectar,elapsed:state.elapsed,jumps:state.jumps,falls:state.falls,collected:[...state.collected],bestCombo:state.bestCombo,shield:state.shield}))}catch{}}
function start(resume=false){
 Object.assign(state,{mode:'play',current:0,progress:0,checkpoint:0,selected:1,charge:0,charging:false,flight:null,elapsed:0,nectar:0,jumps:0,falls:0,combo:0,bestCombo:0,shield:false,chapter:0,collected:new Set(),landingTime:0,respawn:0});
 pads.forEach(p=>{p.sink=0;p.visited=false});
 if(resume&&saved){Object.assign(state,{current:saved.checkpoint,progress:saved.checkpoint,checkpoint:saved.checkpoint,nectar:saved.nectar||0,elapsed:saved.elapsed||0,jumps:saved.jumps||0,falls:saved.falls||0,bestCombo:saved.bestCombo||0,shield:!!saved.shield,collected:new Set(saved.collected||[])});}
 state.chapter=Math.min(2,Math.floor(state.progress/10));setTheme(state.chapter);$('jump').disabled=false;$('jump').classList.remove('charging');$('jump-label').textContent='按住 · 蓄力';$('pause').textContent='Ⅱ';state.landingTime=worldTime;frog.visible=true;frog.position.copy(currentPad().group.position);frog.position.y=padTop(currentPad());frog.scale.setScalar(1);frog.rotation.y=0;
 ['intro','chapter-card','scene-caption','intro-footer'].forEach(id=>$(id).classList.add('hidden'));['hud','play-controls','checkpoint'].forEach(id=>$(id).classList.remove('hidden'));document.body.classList.add('playing');hideModal();selectDefault();updateHud();toast(resume?'回到荷花存档点，继续冒险。':'按住空格蓄力，在浅色区域松开。',5);initAudio();
}
function updateHud(){$('progress-count').textContent=`${state.progress} / ${TOTAL}`;$('progress-fill').style.width=`${state.progress/TOTAL*100}%`;$('progress-label').textContent=state.progress===0?'第一片荷叶':state.progress===30?'到达月光花岛':`已跃过 ${state.progress} 片荷叶`;$('area-label').textContent=`CHAPTER 0${state.chapter+1} · ${CHAPTERS[state.chapter].name}`;$('nectar').textContent=state.nectar;$('timer').textContent=timeFormat(state.elapsed);$('checkpoint').innerHTML=`⚑ <span>${state.checkpoint?`第 ${state.checkpoint} 片 · 已存档`:'出发荷叶'}${state.shield?' · 水滴护盾已就绪':''}</span>`;$('combo').classList.toggle('hidden',state.combo<2);$('combo').textContent=`${state.combo} 连 · 完美落点`;shieldRing.visible=state.shield;}
function timeFormat(time){return `${Math.floor(time/60).toString().padStart(2,'0')}:${Math.floor(time%60).toString().padStart(2,'0')}`}
function beginCharge(){if(state.mode!=='play'||state.flight||state.respawn>0||state.charging)return;state.charging=true;state.charge=0;$('jump').classList.add('charging');initAudio();}
function cancelCharge(){state.charging=false;state.charge=0;$('jump').classList.remove('charging');$('jump-label').textContent='按住 · 蓄力';}
function releaseCharge(){if(!state.charging)return;if(state.mode!=='play'){cancelCharge();return}const target=selectedPad(),cur=currentPad();if(!target){cancelCharge();return}const from=frog.position.clone(),dir=new THREE.Vector3(target.group.position.x-from.x,0,target.group.position.z-from.z).normalize(),range=jumpRange(state.charge,cur.type==='spring');const to=from.clone().addScaledVector(dir,range);to.y=padTop(target);state.flight={from,to,age:0,duration:.74+state.charge*.27,height:1.7+state.charge*1.0+(cur.type==='spring'?1.2:0),origin:state.current};state.jumps++;frog.rotation.y=Math.atan2(-dir.x,-dir.z);cancelCharge();melody('jump');splash(from.x,from.z,true);$('jump-label').textContent='跃向世界';$('jump').disabled=true;}
function land(p){const center=distance(frog.position,p.group.position),perfect=center<p.r*.43;state.current=p.id;state.progress=Math.max(state.progress,p.index);p.visited=true;state.landingTime=worldTime;frog.position.y=padTop(p);state.flight=null;$('jump').disabled=false;$('jump-label').textContent='按住 · 蓄力';
 if(perfect){state.combo++;state.bestCombo=Math.max(state.bestCombo,state.combo)}else state.combo=0;
 if(!state.collected.has(p.id)){state.collected.add(p.id);const earned=p.type==='bonus'?15:3+(perfect?2:0)+Math.min(3,Math.max(0,state.combo-1));state.nectar+=earned;if(p.type==='shield'){state.shield=true;toast('水滴护盾 · 下一次落水可原地获救',4)}else if(p.type==='bonus'){toast(`发现秘密露光！ +${earned}`,3)}else if(perfect&&state.combo>=2){toast(`完美落点 · ${state.combo} 连跃  +${earned}`,2)}melody('collect')}else melody('land');
 splash(frog.position.x,frog.position.z,true);
 if(p.type==='checkpoint'){state.checkpoint=p.index;saveProgress();if(p.index>0&&p.index<30)toast(`荷花存档点 · 第 ${p.index} 片`,3)}
 const chapter=Math.min(2,Math.floor(state.progress/10));if(chapter!==state.chapter){state.chapter=chapter;setTheme(chapter);toast(chapter===1?'进入流萤水道 · 留意缓缓漂移的荷叶':'进入月影深潭 · 金褐色荷叶将在 3 秒后下沉',5)}
 if(p.type==='sinking')toast('荷叶开始下沉了！3 秒内再次起跳',2.5);if(p.type==='spring')toast('弹跳花已就绪 · 下一跳距离与高度提升',3);
 updateHud();if(p.index>=TOTAL&&p.type!=='bonus'){win();return}selectDefault();}
function fall(){if(state.respawn>0)return;state.falls++;state.combo=0;state.flight=null;cancelCharge();splash(frog.position.x,frog.position.z);melody('fall');frog.visible=false;state.respawn=.85;$('jump').disabled=true;const protectedByShield=state.shield;if(protectedByShield){state.shield=false;toast('水滴护盾接住了你，再试一次！',3)}else{state.current=state.checkpoint;state.progress=state.checkpoint;toast('扑通！回到存档点，再勇敢一次。',3)}state.chapter=Math.min(2,Math.floor(state.progress/10));setTheme(state.chapter);updateHud();}
function respawn(){pads.forEach(p=>p.sink=0);const p=currentPad();p.group.position.y=.18;frog.position.copy(p.group.position);frog.position.y=padTop(p);frog.visible=true;frog.scale.setScalar(1);state.landingTime=worldTime;state.respawn=0;$('jump').disabled=false;$('jump-label').textContent='按住 · 蓄力';selectDefault();}
function win(){state.mode='win';cancelCharge();targetRing.visible=false;targetDot.visible=false;const score=state.nectar+Math.max(0,300-Math.floor(state.elapsed))+state.bestCombo*10;const stars=state.falls===0?3:state.falls<7?2:1;const newBest=!best||score>best.score;if(newBest){best={score,time:state.elapsed,nectar:state.nectar};try{localStorage.setItem('lilybound-best',JSON.stringify(best))}catch{}}try{localStorage.removeItem('lilybound-save')}catch{};showModal('冒险，在此开花。','THE MOONLIT FINISH',`<div class="stars">${'★'.repeat(stars)}${'☆'.repeat(3-stars)}</div><p class="modal-note">你穿过晨光、流萤与月色，终于找到了荷塘深处的那朵花。</p><div class="result-stats"><div><b>${score}</b><small>冒险分数</small></div><div><b>${state.nectar}</b><small>收集露光</small></div><div><b>${timeFormat(state.elapsed)}</b><small>完成时间</small></div></div><div class="achievement">${newBest?'个人新纪录！ · ':''}${state.falls===0?'无伤荷塘大师':state.bestCombo>=5?'精准跳跃家':'勇敢的小小探险家'} · 最长 ${state.bestCombo} 次完美连跃</div>`,[{label:'再冒险一次',fn:()=>start(false)},{label:'回到荷塘',secondary:true,fn:goHome}]);[0,160,320,480].forEach((t,i)=>setTimeout(()=>tone([523,659,784,1046][i],.5,'sine',.03),t));}
let modalReturn='intro';
function showModal(title,eyebrow,html,actions){$('modal-title').textContent=title;$('modal-eyebrow').textContent=eyebrow;$('modal-content').innerHTML=html;$('modal-actions').replaceChildren();for(const action of actions){const b=document.createElement('button');b.textContent=action.label;if(action.secondary)b.classList.add('secondary');b.addEventListener('click',action.fn);$('modal-actions').append(b)}$('modal-backdrop').classList.remove('hidden');$('close-modal').focus()}
function hideModal(){$('modal-backdrop').classList.add('hidden');}
function closeModal(){hideModal();if(state.mode==='paused'){state.mode=modalReturn;$('pause').textContent='Ⅱ';}if(state.mode==='win')goHome();}
function pause(){if(state.mode==='paused'){closeModal();return}if(state.mode!=='play')return;modalReturn=state.mode;state.mode='paused';cancelCharge();$('pause').textContent='▷';showModal('歇一歇，听听风。','A MOMENT BY THE POND',`<p class="modal-note">已经走过 ${state.progress} 片荷叶，收集了 ${state.nectar} 点露光。<br>当前旅程用时 ${timeFormat(state.elapsed)}。</p><div class="achievement">目标：到达第 30 片荷叶上的月光花岛。</div>`,[{label:'继续冒险',fn:closeModal},{label:'重新出发',secondary:true,fn:()=>start(false)},{label:'操作说明',secondary:true,fn:guide}]);}
function guide(){if(state.mode==='play'){modalReturn='play';state.mode='paused';cancelCharge()}showModal('跳跃，很简单。','FIELD NOTES',`<div class="guide-row"><b>1</b><div><strong>选一片荷叶</strong><p>点击前方荷叶，或用左右方向键切换。浅色光圈就是你的目标。</p></div></div><div class="guide-row"><b>2</b><div><strong>按住蓄力，松开起跳</strong><p>按住空格或右下方按钮，在蓄力条的浅色区域松开。蓄力越久，跳得越远。</p></div></div><div class="guide-row"><b>3</b><div><strong>让好奇心带路</strong><p>收集露光，探索金色支线。落在荷叶中心可获得连跃奖励；荷花每 5 片保存进度。</p></div></div><p class="modal-note">蓝绿荷叶会漂移 · 金褐荷叶会下沉<br>粉色弹跳花增加跳距 · 水滴护盾抵挡一次落水<br>Esc 暂停 · R 回到存档点 · M 切换声音</p>`,[{label:'知道了',fn:closeModal}]);}
function goHome(){hideModal();state.mode='intro';cancelCharge();state.flight=null;state.current=0;state.progress=0;state.respawn=0;frog.visible=true;frog.scale.setScalar(1);frog.rotation.y=.62;setTheme(0);document.body.classList.remove('playing');['intro','chapter-card','scene-caption','intro-footer'].forEach(id=>$(id).classList.remove('hidden'));['hud','play-controls','checkpoint','combo'].forEach(id=>$(id).classList.add('hidden'));try{saved=JSON.parse(localStorage.getItem('lilybound-save'))}catch{};$('continue').hidden=!(saved&&saved.checkpoint>0&&saved.checkpoint<TOTAL);}

const raycaster=new THREE.Raycaster(),pointer=new THREE.Vector2();
$('world').addEventListener('pointerdown',event=>{if(state.mode!=='play'||state.flight||state.charging)return;pointer.set(event.clientX/innerWidth*2-1,-event.clientY/innerHeight*2+1);raycaster.setFromCamera(pointer,camera);const hit=raycaster.intersectObjects(pads.map(p=>p.body));if(!hit.length)return;const id=hit[0].object.userData.padId;if(candidates().some(p=>p.id===id)){state.selected=id;updateTarget();tone(500,.06,'sine',.015)}else if(id!==state.current)toast('选一片更近的前方荷叶',2)});
$('start').addEventListener('click',()=>start());$('continue').addEventListener('click',()=>start(true));$('show-guide').addEventListener('click',guide);$('home').addEventListener('click',e=>{e.preventDefault();if(state.mode==='play')pause();else if(state.mode==='intro')goHome()});$('pause').addEventListener('click',()=>state.mode==='intro'?guide():pause());$('close-modal').addEventListener('click',closeModal);$('prev-target').addEventListener('click',()=>cycleTarget(-1));$('next-target').addEventListener('click',()=>cycleTarget(1));
function toggleSound(){state.audio=!state.audio;initAudio();$('sound').innerHTML=state.audio?'♪':'♪<span class="mute-strike"></span>';$('sound').title=state.audio?'关闭声音':'开启声音';$('sound').setAttribute('aria-label',$('sound').title);if(state.audio)tone(720,.18,'sine',.03)}$('sound').addEventListener('click',toggleSound);
document.querySelectorAll('.chapter').forEach((el,i)=>el.addEventListener('click',()=>{if(state.mode==='intro')setTheme(i)}));
$('jump').addEventListener('pointerdown',e=>{e.preventDefault();$('jump').setPointerCapture(e.pointerId);beginCharge()});$('jump').addEventListener('pointerup',e=>{e.preventDefault();releaseCharge()});$('jump').addEventListener('pointercancel',cancelCharge);$('jump').addEventListener('contextmenu',e=>e.preventDefault());
document.addEventListener('keydown',e=>{if(e.code==='Space'&&state.mode==='play'){e.preventDefault();if(!e.repeat)beginCharge()}if(e.code==='ArrowLeft'||e.code==='KeyA'){e.preventDefault();cycleTarget(-1)}if(e.code==='ArrowRight'||e.code==='KeyD'){e.preventDefault();cycleTarget(1)}if(e.code==='Escape'){if(!$('modal-backdrop').classList.contains('hidden'))closeModal();else pause()}if(e.code==='KeyM'&&!e.repeat)toggleSound();if(e.code==='KeyR'&&!e.repeat&&state.mode==='play'&&!state.respawn){state.combo=0;cancelCharge();state.flight=null;state.current=state.checkpoint;state.progress=state.checkpoint;state.chapter=Math.min(2,Math.floor(state.progress/10));setTheme(state.chapter);respawn();updateHud();toast('已回到最近的荷花存档点',2)}});
document.addEventListener('keyup',e=>{if(e.code==='Space'){e.preventDefault();releaseCharge()}});
window.addEventListener('blur',()=>{cancelCharge();if(state.mode==='play')pause()});document.addEventListener('visibilitychange',()=>{if(document.hidden){cancelCharge();if(state.mode==='play')pause()}});
document.addEventListener('keydown',e=>{if(e.code==='Tab'&&!$('modal-backdrop').classList.contains('hidden')){const focusable=[...$('modal-backdrop').querySelectorAll('button')];if(e.shiftKey&&document.activeElement===focusable[0]){e.preventDefault();focusable.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===focusable.at(-1)){e.preventDefault();focusable[0].focus()}}});

let worldTime=0,blinkAt=3,blink=0;const camLook=new THREE.Vector3(0,0,-3),camGoal=new THREE.Vector3(),lookGoal=new THREE.Vector3();
function animate(){requestAnimationFrame(animate);const dt=Math.min(clock.getDelta(),.05);if(state.mode!=='paused')worldTime+=dt;
 const theme=CHAPTERS[state.preview];waterUniforms.time.value=worldTime;waterUniforms.color.value.lerp(new THREE.Color(theme.water),dt*.8);scene.fog.color.lerp(new THREE.Color(theme.fog),dt*.8);scene.background.copy(scene.fog.color);sun.color.lerp(new THREE.Color(theme.light),dt*.8);hemi.color.lerp(new THREE.Color(theme.ambient),dt*.8);
 for(const p of pads){const prevX=p.group.position.x,prevZ=p.group.position.z;if(p.type==='moving'){p.group.position.x=p.baseX+Math.sin(worldTime*.8+p.phase)*.5;p.group.position.z=p.baseZ+Math.cos(worldTime*.6+p.phase)*.22;}p.group.position.y=.18+Math.sin(worldTime*1.35+p.phase)*.045-p.sink;p.group.rotation.z=Math.sin(worldTime*.8+p.phase)*.012;p.shadow.position.x=p.group.position.x;p.shadow.position.z=p.group.position.z;if(p.id===state.current&&!state.flight&&state.mode==='play'){frog.position.x+=p.group.position.x-prevX;frog.position.z+=p.group.position.z-prevZ;}}
 for(const item of collectables){const p=item.pad;item.group.visible=!state.collected.has(p.id);item.group.position.set(p.group.position.x,padTop(p)+.8+Math.sin(worldTime*2+p.phase)*.16,p.group.position.z);item.core.rotation.y=worldTime*1.3;item.core.rotation.z=Math.sin(worldTime+p.phase)*.2;}
 for(const d of dragonflies){d.g.position.set(d.x+Math.sin(worldTime*.4+d.phase)*1.5,1.1+Math.sin(worldTime*1.5+d.phase)*.25,d.z+Math.cos(worldTime*.3+d.phase));d.g.rotation.y=worldTime*.3+d.phase;for(const w of d.wings)w.rotation.z=Math.sin(worldTime*70)*.3;}
 for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.age+=dt;p.v.y-=5*dt;p.m.position.addScaledVector(p.v,dt);p.m.material.opacity=Math.max(0,1-p.age/p.life)*.8;if(p.age>p.life){scene.remove(p.m);p.m.geometry.dispose();p.m.material.dispose();particles.splice(i,1)}}
 for(let i=ripples.length-1;i>=0;i--){const r=ripples[i];r.age+=dt;r.m.visible=r.age>0;r.m.scale.setScalar(.35+Math.max(0,r.age)*2.3);r.m.material.opacity=Math.max(0,.27*(1-r.age/1.8));if(r.age>1.8){scene.remove(r.m);r.m.geometry.dispose();r.m.material.dispose();ripples.splice(i,1)}}
 if(state.toastTime>0&&state.mode!=='paused'){state.toastTime-=dt;if(state.toastTime<=0)$('toast').classList.remove('show');}
 if(state.mode==='intro'){frog.position.set(0,padTop(pads[0])+.015*Math.sin(worldTime*2),0);frog.rotation.y=Math.PI+.45+Math.sin(worldTime*.5)*.06;frog.scale.setScalar(1.15);body.scale.y=.43+Math.sin(worldTime*2)*.012;}
 if(state.mode==='play'){
  state.elapsed+=dt;$('timer').textContent=timeFormat(state.elapsed);
  if(state.respawn>0){state.respawn-=dt;if(state.respawn<=0)respawn()}
  else if(state.flight){const f=state.flight;f.age+=dt;const t=Math.min(1,f.age/f.duration);frog.position.lerpVectors(f.from,f.to,t);frog.position.y+=Math.sin(t*Math.PI)*f.height;const stretch=1+Math.sin(t*Math.PI)*.12;frog.scale.set(1/Math.sqrt(stretch),stretch,1/Math.sqrt(stretch));for(const leg of legs)leg.rotation.x=Math.sin(t*Math.PI)*.5;if(t>=1){const p=pads.filter(p=>p.sink<.38&&distance(frog.position,p.group.position)<p.r-.18).sort((a,b)=>distance(frog.position,a.group.position)-distance(frog.position,b.group.position))[0];if(p)land(p);else fall()}}
  else{const p=currentPad();frog.position.y=padTop(p);if(state.charging){state.charge=Math.min(1,state.charge+dt/.98);frog.scale.y=1-state.charge*.28;frog.scale.x=frog.scale.z=1+state.charge*.12;$('charge-text').textContent=`蓄力 ${Math.round(state.charge*100)}%`;$('jump-label').textContent='松开 · 跳跃';}else{frog.scale.lerp(new THREE.Vector3(1,1,1),dt*12);$('charge-text').textContent=p.type==='sinking'?`还剩 ${Math.max(0,3-(worldTime-state.landingTime)).toFixed(1)} 秒`:'准备起跳';}if(p.type==='sinking'){const held=worldTime-state.landingTime;p.sink=Math.max(0,held/3)*.20;if(held>2.3)p.group.rotation.z+=Math.sin(worldTime*35)*.06;if(held>3)fall()}}
 }
 const target=selectedPad(),cur=currentPad();const active=state.mode==='play'&&!state.flight&&state.respawn<=0;targetRing.visible=active;targetDot.visible=active;landingRing.visible=active&&state.charging;
 if(target){const d=distance(frog.position,target.group.position),safe=safeCharge(d,target.r,cur.type==='spring');$('safe-zone').style.left=`${clamp(safe[0],0,1)*100}%`;$('safe-zone').style.width=`${Math.max(0,safe[1]-safe[0])*100}%`;$('charge-fill').style.width=`${state.charge*100}%`;$('charge-mark').style.left=`${state.charge*100}%`;targetRing.position.copy(target.group.position);targetRing.position.y=padTop(target)+.04;targetRing.scale.setScalar(target.r*.94);targetRing.material.opacity=.65+Math.sin(worldTime*3)*.2;targetDot.position.set(target.group.position.x,padTop(target)+1.45+Math.sin(worldTime*3)*.1,target.group.position.z);
 const dir=new THREE.Vector3(target.group.position.x-frog.position.x,0,target.group.position.z-frog.position.z).normalize(),range=state.charging?jumpRange(state.charge,cur.type==='spring'):d;
 for(let i=0;i<arcDots.length;i++){const dot=arcDots[i];dot.visible=active;const t=(i+1)/(arcDots.length+1);dot.position.copy(frog.position).addScaledVector(dir,range*t);dot.position.y+=Math.sin(t*Math.PI)*(state.charging?1.7+state.charge:1.9);dot.material.opacity=state.charging?.6:.23;dot.scale.setScalar(state.charging?1:.7)}landingRing.position.copy(frog.position).addScaledVector(dir,range);landingRing.position.y=padTop(target)+.06;}
 if(state.mode==='intro'){arcDots.forEach(d=>d.visible=false);if(innerWidth>760){camGoal.set(12,16,21);lookGoal.set(-3.7,.1,-4.8)}else{camGoal.set(11,17,23);lookGoal.set(-2.5,.1,-3.5)}}else{const pos=frog.position;const z=state.respawn>0?cur.group.position.z:pos.z;const x=state.respawn>0?cur.group.position.x:pos.x;if(innerWidth>760){camGoal.set(x+8.4,15.2,z+15.8);lookGoal.set(x*.6,.3,z-4.8)}else{camGoal.set(x+6.2,19.5,z+17.4);lookGoal.set(x*.45,.2,z-5.8)}}
 const smooth=1-Math.exp(-dt*3.3);camera.position.lerp(camGoal,smooth);camLook.lerp(lookGoal,smooth);camera.lookAt(camLook);sun.position.set(camLook.x-15,28,camLook.z+12);sun.target.position.copy(camLook);frogShadow.position.set(frog.position.x,Math.max(.04,padTop(cur)+.012),frog.position.z);frogShadow.visible=state.respawn<=0;frogShadow.material.opacity=state.flight?.12:.25;shieldRing.rotation.z=worldTime*.5;
 if(state.audio&&state.mode!=='paused'&&worldTime-lastAmbient>4){lastAmbient=worldTime;tone([196,220,261.6,293.7][Math.floor(Math.random()*4)],2,'sine',.006);if(Math.random()>.45)setTimeout(()=>tone(1400+Math.random()*600,.12,'sine',.008,900),500);}
 renderer.render(scene,camera);
}
window.addEventListener('resize',()=>{renderer.setSize(innerWidth,innerHeight);camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();});
